package com.codequest.academy.shared.labs

object PythonExercises {
    private fun exercise(id: String, lesson: String, title: String, statement: String, starter: String, solution: String, tests: List<String>, explanation: String) = PythonExercise(
        id, lesson, title, "Implement and test $title using Python.", statement, starter, solution,
        tests.mapIndexed { i, code -> PythonTest("Case ${i + 1}", code, i > 0) },
        listOf("Identify the expected input and return value before writing code.", explanation), explanation
    )
    val all = listOf(
        exercise("py-types", "S02-L01", "Variables and types", "Define quantity = 4 and price = 2.5. Store their product in total (10.0).", "quantity = 4\nprice = 2.5\n# Calculate total\n", "quantity=4\nprice=2.5\ntotal=quantity*price", listOf("assert total == 10.0", "assert isinstance(total, float)"), "Multiplying an integer by a float produces a float."),
        exercise("py-conditions", "S02-L02", "Boolean decisions", "Write eligible(age, consent): return True only when age is at least 18 and consent is True.", "def eligible(age, consent):\n    pass\n", "def eligible(age,consent):\n    return age>=18 and consent", listOf("assert eligible(18, True) is True", "assert eligible(17, True) is False\nassert eligible(20, False) is False"), "Both conditions must hold, so combine them with and."),
        exercise("py-loops", "S02-L03", "Loops and accumulation", "Return the sum of even numbers in values. Empty input returns 0.", "def even_sum(values):\n    pass\n", "def even_sum(values):\n    total=0\n    for value in values:\n        if value%2==0: total+=value\n    return total", listOf("assert even_sum([1,2,3,4]) == 6", "assert even_sum([])==0\nassert even_sum([-2,3,8])==6"), "Initialize an accumulator, test each number modulo 2, and add matching values."),
        exercise("py-functions", "S02-L04", "Functions", "Return the arithmetic mean of values. Raise ValueError for an empty list.", "def mean(values):\n    pass\n", "def mean(values):\n    if not values: raise ValueError('empty')\n    return sum(values)/len(values)", listOf("assert mean([2,4,6])==4", "try:\n mean([])\n raise AssertionError('Expected ValueError')\nexcept ValueError: pass"), "A function exposes a clear contract, including invalid input behavior."),
        exercise("py-collections", "S02-L05", "Collections", "Return (unique_sorted, counts): a sorted list of unique words and a dictionary of frequencies.", "def summarize(words):\n    pass\n", "def summarize(words):\n    counts={}\n    for word in words: counts[word]=counts.get(word,0)+1\n    return sorted(set(words)), counts", listOf("assert summarize(['a','b','a']) == (['a','b'], {'a':2,'b':1})", "assert summarize([])==([],{})"), "Sets remove duplicates, dictionaries associate keys and counts, and a tuple groups results."),
        exercise("py-files", "S03-L01", "Files and exceptions", "Write save_numbers(values): save one integer per line in numbers.txt, then return the integers read back. Use a context manager.", "def save_numbers(values):\n    pass\n", "def save_numbers(values):\n    with open('numbers.txt','w') as f:\n        f.write('\\n'.join(map(str,values)))\n    with open('numbers.txt') as f:\n        return [int(x) for x in f.read().splitlines()]", listOf("assert save_numbers([3,5])==[3,5]", "assert save_numbers([])==[]\nassert save_numbers([-2,0])==[-2,0]"), "Only the disposable run workspace is writable. A with block closes the file even if an exception occurs."),
        exercise("py-modules", "S03-L02", "Modules", "Use the standard math module to return the Euclidean distance from (0,0) to (x,y).", "import math\ndef distance(x,y):\n    pass\n", "import math\ndef distance(x,y):\n    return math.hypot(x,y)", listOf("assert distance(3,4)==5", "assert distance(0,0)==0\nassert distance(-3,4)==5"), "math.hypot computes the norm robustly. Packages are preinstalled; network installation is unavailable."),
        exercise("py-debug", "S03-L03", "Testing and debugging", "Repair last(values) so it returns the final item, or None for an empty list.", "def last(values):\n    return values[len(values)]\n", "def last(values):\n    return values[-1] if values else None", listOf("assert last([2,4])==4", "assert last([]) is None\nassert last([0])==0"), "Python indexes start at zero. The final index is len(values)-1, or -1."),
        exercise("py-complexity", "S04-L01", "Complexity and profiling", "Write prefix_sums(values) using one pass. For [2,3,1], return [2,5,6].", "def prefix_sums(values):\n    pass\n", "def prefix_sums(values):\n    total=0\n    result=[]\n    for value in values:\n        total+=value\n        result.append(total)\n    return result", listOf("assert prefix_sums([2,3,1])==[2,5,6]", "assert prefix_sums([])==[]\nassert prefix_sums([1]*10000)[-1]==10000"), "A running total requires O(n) operations and O(n) output storage. Tests check correctness; inspect the loop to justify complexity."),
        exercise("py-search", "S04-L02", "Binary search", "Return the index of target in a sorted list, or -1. Avoid linear scanning.", "def find(values,target):\n    pass\n", "def find(values,target):\n    lo,hi=0,len(values)-1\n    while lo<=hi:\n        mid=(lo+hi)//2\n        if values[mid]==target: return mid\n        if values[mid]<target: lo=mid+1\n        else: hi=mid-1\n    return -1", listOf("assert find([1,3,5,7],5)==2", "assert find([],2)==-1\nassert find([1,3,5],4)==-1\nassert find([1],1)==0"), "Discard half the remaining interval per iteration: O(log n) comparisons."),
        exercise("py-numpy", "S05-L01", "NumPy normalization", "Return a NumPy array with each column centered by its mean. Input is a nonempty 2D array.", "import numpy as np\ndef center(x):\n    pass\n", "import numpy as np\ndef center(x):\n    x=np.asarray(x,dtype=float)\n    return x-x.mean(axis=0)", listOf("assert np.allclose(center([[1,2],[3,4]]),[[-1,-1],[1,1]])", "assert np.allclose(center([[2,5,8]]),[[0,0,0]])"), "axis=0 computes one mean per feature; broadcasting subtracts it from each observation."),
        exercise("py-pandas", "S06-L01", "Pandas missing data", "Return a new DataFrame with missing values in score replaced by the nonmissing mean. Do not modify the input.", "import pandas as pd\ndef clean(df):\n    pass\n", "import pandas as pd\ndef clean(df):\n    result=df.copy()\n    result['score']=result['score'].fillna(result['score'].mean())\n    return result", listOf("assert clean(pd.DataFrame({'score':[2,None,4]}))['score'].tolist()==[2,3,4]", "d=pd.DataFrame({'score':[1,None,3]})\nclean(d)\nassert d['score'].isna().sum()==1"), "Copy before transformation. In ML pipelines, fit the fill value on training data only."),
        exercise("py-ml", "S12-L01", "Train/test preparation", "Split values at floor(0.8*n), preserving order. Return (training, test) as lists. Never mix test observations into training.", "def split(values):\n    pass\n", "def split(values):\n    cut=int(len(values)*0.8)\n    return list(values[:cut]),list(values[cut:])", listOf("assert split(list(range(10)))==(list(range(8)),[8,9])", "assert split([])==([],[])\nassert split([1])==([],[1])"), "An ordered split can model future holdout data. Fit preprocessing only on training observations; compare a baseline on untouched test data.")
    )
}
